sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {

        var result = [];

        // Optional: get query parameters
        var eventId = request.queryParams.event_id;
        var status = request.queryParams.status;

        var gr = new GlideRecord('x_1558402_smart_0_external_event_id');

        // ✅ Apply filters if passed
        if (eventId) {
            gr.addQuery('event_id', eventId);
        }

        if (status) {
            gr.addQuery('status', status);
        }

        gr.query();

        // ✅ Loop through records
        while (gr.next()) {

            result.push({
                event_id: gr.getValue('event_id'),
                description: gr.getValue('description'),
                priority: gr.getValue('priority'),
                asset: gr.getDisplayValue('asset'),
                customer: gr.getDisplayValue('customer'),
                status: gr.getValue('status'),
                created_on: gr.getValue('sys_created_on')
            });
        }

        // ✅ Response
        response.setStatus(200);
        response.setBody({
            count: result.length,
            data: result
        });

    } catch (e) {

        gs.error("GET API Error: " + e.message);

        response.setStatus(500);
        response.setBody({
            message: "Error fetching event records"
        });
    }

})(request, response);
